def simple_graph_exists(degrees):
    n = len(degrees)
    if sum(degrees) % 2:
        return False                       # handshaking lemma
    d = sorted(degrees, reverse=True)
    pre = [0] * (n + 1)                    # pre[k] = sum of the k largest degrees
    for i, x in enumerate(d):
        pre[i + 1] = pre[i] + x
    p = n                                  # p = number of degrees >= k (only shrinks as k grows)
    for k in range(1, n + 1):
        while p > 0 and d[p - 1] < k:
            p -= 1
        m = max(p, k)
        # Erdos-Gallai: sum of k largest <= k(k-1) + sum_{i>k} min(d_i, k)
        rhs = k * (k - 1) + k * (m - k) + (pre[n] - pre[m])
        if pre[k] > rhs:
            return False
    return True
